
#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Entities;
using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2.Vanilla.Enemies;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.creeper)]
    public class Creeper : AIEntityBehaviour
    {
        public Creeper(string nsp, string name) : base(nsp, name)
        {
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.SetProperty(PROP_CHARGE, 0);
            UpdateChargingScale(entity, 0);
        }

        // 被闪电击中时进入充能状态
        public override void PostTakeDamage(DamageOutput result)
        {
            base.PostTakeDamage(result);

            if (result.BodyResult == null)
                return;

            if (result.BodyResult.Effects.HasEffect(
                VanillaDamageEffects.LIGHTNING))
            {
                var entity = result.Entity;

                if (!entity.HasBuff<CreeperChargedBuff>())
                {
                    entity.AddBuff<CreeperChargedBuff>();
                }
            }
        }

        protected override void UpdateAI(Entity entity)
        {
            // 每帧调用基类 AI
            base.UpdateAI(entity);

            // 死亡后不再干预实体状态
            if (entity.IsDead)
            {
                UpdateChargingScale(entity, 0);
                return;
            }

            var charge = entity.GetProperty<int>(PROP_CHARGE);

            if (CreeperFearBehaviour.IsFearing(entity))
            {
                entity.State = LogicEnemyStates.WALK;
                entity.SetCasting(false);
                entity.RemoveBuffs<CreeperChargingBuff>();
                charge = Mathf.Max(charge - 1, 0);
                entity.SetProperty(PROP_CHARGE, charge);
                UpdateChargingScale(entity, charge);
                return;
            }

            bool hasTarget = chargeDetector.DetectExists(entity);

            if (hasTarget || charge > 0)
            {
                // 蓄力期间停止移动
                entity.State = LogicEnemyStates.IDLE;
                entity.SetCasting(true);

                // 仅在开始蓄力时添加效果和播放音效
                if (charge == 0)
                {
                    entity.AddBuff<CreeperChargingBuff>();
                    entity.PlaySound(VanillaSoundID.creeperFuse, 1);
                }

                // 绝缘期间蓄力倒计时冻结：已有蓄力（charge ≥ 1）时只允许减少、不允许增加
                // （charge 为 0 时照常涨到 1，保证“开始蓄力”的判定只触发一次，不反复刷闪白和嘶声）
                charge = hasTarget
                    ? (entity.HasBuff<InsulatedBuff>() && charge > 0 ? charge : Mathf.Min(charge + 1, CHARGE_MAX))
                    : Mathf.Max(charge - 1, 0);

                entity.SetProperty(PROP_CHARGE, charge);
                UpdateChargingScale(entity, charge);

                // 蓄力完成，执行爆炸
                if (charge >= CHARGE_MAX)
                {
                    OnChargeCompleted(entity);
                }
            }
            else
            {
                entity.State = LogicEnemyStates.WALK;
                entity.SetCasting(false);
                entity.RemoveBuffs<CreeperChargingBuff>();
                UpdateChargingScale(entity, 0);
            }
        }

        protected virtual void OnChargeCompleted(Entity entity)
        {
            Explode(entity, entity.GetDamage() * 3, 2);
            entity.Remove();
        }

        private static void UpdateChargingScale(Entity entity, int charge)
        {
            int remainingCharge = CHARGE_MAX - charge;
            float scale = 1;

            if (remainingCharge < EXPAND_DURATION)
            {
                scale = Mathf.Lerp(
                    EXPAND_SCALE,
                    1,
                    remainingCharge / (float)EXPAND_DURATION
                );
            }

            entity.SetDisplayScale(Vector3.one * scale);
        }

        // 普通爆炸入口
        public static void Explode(Entity entity, float damage, int faction)
        {
            var effects = new DamageEffectList(
                VanillaDamageEffects.EXPLOSION,
                VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN,
                VanillaDamageEffects.MUTE
            );

            Explode(entity, damage, effects, faction);
        }

        public static void Explode(
            Entity entity,
            float damage,
            DamageEffectList effects,
            int faction)
        {
            Explode(entity, damage, entity.GetRange(), effects, faction);
        }

       // 实际爆炸执行
public static void Explode(
    Entity entity,
    float damage,
    float range,
    DamageEffectList effects,
    int faction)
{
    var scale = entity.GetFinalScale();
    var scaleX = Mathf.Abs(scale.x);

    // 闪电充能后爆炸伤害翻倍
    float damageMultiplier =
        entity.HasBuff<CreeperChargedBuff>() ? 2f : 1f;

    var radius = range * scaleX;

    entity.Explode(
        entity.GetCenter(),
        radius,
        faction,
        damage * damageMultiplier,
        effects
    );

    Explosion.Spawn(entity, entity.GetCenter(), radius);
    // 冲击波：伤害为 79，半径为基础爆炸半径的 2.5 倍
    float shockwaveDamage = damage > 0 ? 79f * damageMultiplier : 0;
    float shockwaveRadius = radius * 2.5f;

    entity.Explode(
        entity.GetCenter(),
        shockwaveRadius,
        faction,
        shockwaveDamage,
        effects
    );
    entity.PlaySound(
        VanillaSoundID.explosion,
        scaleX == 0 ? 1000 : 1 / scaleX
    );
}

        // 蓄力检测器
        private static Detector chargeDetector =
            new MutantZombieDetector(-20)
            {
                canDetectInvisible = true
            };

        public static readonly VanillaEntityPropertyMeta<int> PROP_CHARGE =
            new VanillaEntityPropertyMeta<int>("charge");

        public const int CHARGE_MAX = 90;
        public const int EXPAND_DURATION = 5;
        public const float EXPAND_SCALE = 1.5f;
    }
}
